
CREATE TABLE IF NOT EXISTS vp_meta(meta_key VARCHAR(80) PRIMARY KEY,value BIGINT NOT NULL) ENGINE=InnoDB;
INSERT IGNORE INTO vp_meta VALUES('revision',1);
CREATE TABLE IF NOT EXISTS vp_users(id VARCHAR(80) COLLATE utf8mb4_bin PRIMARY KEY,name VARCHAR(255) NOT NULL,disabled BOOLEAN NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS vp_nodes(id VARCHAR(80) COLLATE utf8mb4_bin PRIMARY KEY,name VARCHAR(255) NOT NULL,token_hash VARBINARY(32) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT 1,last_seen BIGINT NOT NULL DEFAULT 0,applied_revision BIGINT NOT NULL DEFAULT 0,probe TEXT NOT NULL,errors TEXT NOT NULL,agent_version VARCHAR(80) NOT NULL DEFAULT '',kernel_version VARCHAR(80) NOT NULL DEFAULT '') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS vp_pools(node_id VARCHAR(80) COLLATE utf8mb4_bin NOT NULL,public_ip VARCHAR(64) COLLATE utf8mb4_bin NOT NULL,bind_ip VARCHAR(64) NOT NULL,start_port INT NOT NULL,end_port INT NOT NULL,PRIMARY KEY(node_id,public_ip,start_port),FOREIGN KEY(node_id) REFERENCES vp_nodes(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS vp_plans(id VARCHAR(80) COLLATE utf8mb4_bin PRIMARY KEY,name VARCHAR(255) NOT NULL,port_limit INT NOT NULL,traffic_limit BIGINT NOT NULL,period_days INT NOT NULL,price_cents BIGINT NOT NULL,reset_price_cents BIGINT NOT NULL,node_ids TEXT NOT NULL,enabled BOOLEAN NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS vp_leases(id VARCHAR(80) COLLATE utf8mb4_bin PRIMARY KEY,user_id VARCHAR(80) COLLATE utf8mb4_bin NOT NULL,plan_id VARCHAR(80) COLLATE utf8mb4_bin NOT NULL,plan_name VARCHAR(255) NOT NULL,port_limit INT NOT NULL,traffic_limit BIGINT NOT NULL,period_days INT NOT NULL,node_ids TEXT NOT NULL,expires_at BIGINT NOT NULL,next_reset_at BIGINT NOT NULL,current_cycle VARCHAR(80) COLLATE utf8mb4_bin NOT NULL,manual_paused BOOLEAN NOT NULL DEFAULT 0,ended BOOLEAN NOT NULL DEFAULT 0,KEY lease_user(user_id),KEY lease_reset(next_reset_at,ended),FOREIGN KEY(user_id) REFERENCES vp_users(id),FOREIGN KEY(plan_id) REFERENCES vp_plans(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS vp_cycles(id VARCHAR(80) COLLATE utf8mb4_bin PRIMARY KEY,lease_id VARCHAR(80) COLLATE utf8mb4_bin NOT NULL,started_at BIGINT NOT NULL,ended_at BIGINT NOT NULL DEFAULT 0,reason VARCHAR(40) NOT NULL,up BIGINT NOT NULL DEFAULT 0,down BIGINT NOT NULL DEFAULT 0,FOREIGN KEY(lease_id) REFERENCES vp_leases(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS vp_allocations(id VARCHAR(80) COLLATE utf8mb4_bin PRIMARY KEY,lease_id VARCHAR(80) COLLATE utf8mb4_bin NOT NULL,node_id VARCHAR(80) COLLATE utf8mb4_bin NOT NULL,public_ip VARCHAR(64) NOT NULL,bind_ip VARCHAR(64) NOT NULL,port INT NOT NULL,target_host VARCHAR(253) NOT NULL DEFAULT '',target_port INT NOT NULL DEFAULT 0,released BOOLEAN NOT NULL DEFAULT 0,active_endpoint VARCHAR(240) COLLATE utf8mb4_bin GENERATED ALWAYS AS (IF(released=0,CONCAT(node_id,'/',bind_ip,'/',port),NULL)) STORED,UNIQUE KEY endpoint_unique(active_endpoint),KEY allocation_lease(lease_id,released),FOREIGN KEY(lease_id) REFERENCES vp_leases(id),FOREIGN KEY(node_id) REFERENCES vp_nodes(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS vp_allocation_targets(rule_id VARCHAR(80) COLLATE utf8mb4_bin PRIMARY KEY,targets TEXT NOT NULL,FOREIGN KEY(rule_id) REFERENCES vp_allocations(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS vp_epochs(node_id VARCHAR(80) COLLATE utf8mb4_bin NOT NULL,epoch VARCHAR(80) COLLATE utf8mb4_bin NOT NULL,sequence BIGINT NOT NULL DEFAULT 0,PRIMARY KEY(node_id,epoch),FOREIGN KEY(node_id) REFERENCES vp_nodes(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS vp_cursors(node_id VARCHAR(80) COLLATE utf8mb4_bin NOT NULL,epoch VARCHAR(80) COLLATE utf8mb4_bin NOT NULL,rule_id VARCHAR(80) COLLATE utf8mb4_bin NOT NULL,cycle_id VARCHAR(80) COLLATE utf8mb4_bin NOT NULL,up BIGINT NOT NULL,down BIGINT NOT NULL,PRIMARY KEY(node_id,epoch,rule_id,cycle_id),KEY cursor_rule(rule_id,cycle_id),FOREIGN KEY(node_id) REFERENCES vp_nodes(id),FOREIGN KEY(rule_id) REFERENCES vp_allocations(id),FOREIGN KEY(cycle_id) REFERENCES vp_cycles(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS vp_orders(id VARCHAR(80) COLLATE utf8mb4_bin PRIMARY KEY,user_id VARCHAR(80) COLLATE utf8mb4_bin NOT NULL,plan_id VARCHAR(80) COLLATE utf8mb4_bin NOT NULL,lease_id VARCHAR(80) NOT NULL DEFAULT '',kind VARCHAR(20) NOT NULL,amount_cents BIGINT NOT NULL,status VARCHAR(40) NOT NULL DEFAULT 'pending',created_at BIGINT NOT NULL,paid_at BIGINT NOT NULL DEFAULT 0,snapshot MEDIUMTEXT NOT NULL,FOREIGN KEY(user_id) REFERENCES vp_users(id),FOREIGN KEY(plan_id) REFERENCES vp_plans(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS vp_payment_events(provider VARCHAR(32) COLLATE utf8mb4_bin NOT NULL,transaction_id VARCHAR(80) COLLATE utf8mb4_bin NOT NULL,order_id VARCHAR(80) COLLATE utf8mb4_bin NOT NULL,amount_cents BIGINT NOT NULL,received_at BIGINT NOT NULL,PRIMARY KEY(provider,transaction_id),UNIQUE KEY order_once(order_id),FOREIGN KEY(order_id) REFERENCES vp_orders(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS vp_audit(id BIGINT AUTO_INCREMENT PRIMARY KEY,at BIGINT NOT NULL,event VARCHAR(100) NOT NULL,subject VARCHAR(100) NOT NULL,detail TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
